{
  "name": "color-detect-cli",
  "version": "1.0.0",
  "description": "A Node.js CLI that detects terminal color support before printing colored text.",
  "type": "module",
  "bin": {
    "color-detect": "bin/cli.js"
  },
  "main": "src/color-support.js",
  "exports": {
    ".": "./src/color-support.js"
  },
  "scripts": {
    "start": "node bin/cli.js",
    "test": "node --test"
  },
  "engines": {
    "node": ">=18"
  },
  "files": [
    "bin",
    "src"
  ],
  "license": "MIT"
}

import tty from 'node:tty';

export const LEVEL = {
  NONE: 0,
  BASIC: 1,
  ANSI256: 2,
  TRUECOLOR: 3,
};

function envFlag(name) {
  const value = process.env[name];
  return value !== undefined && value !== '';
}

function forcedLevel() {
  const value = process.env.FORCE_COLOR;
  if (value === undefined) return null;

  if (value === '' || value === '1' || value === 'true') return LEVEL.BASIC;
  if (value === '2') return LEVEL.ANSI256;
  if (value === '3') return LEVEL.TRUECOLOR;
  if (value === '0' || value === 'false') return LEVEL.NONE;

  return LEVEL.BASIC;
}

/**
 * Detect the color level supported by the given stream.
 * Returns one of the LEVEL values: 0 (none), 1 (basic), 2 (256), 3 (truecolor).
 */
export function detectColorLevel(stream = process.stdout) {
  if (envFlag('NO_COLOR')) return LEVEL.NONE;

  const forced = forcedLevel();
  if (forced !== null) return forced;

  if (envFlag('CI')) return LEVEL.NONE;

  if (!tty.isatty(stream.fd)) return LEVEL.NONE;

  const term = process.env.TERM;
  if (term === 'dumb') return LEVEL.NONE;
  if (!term) return LEVEL.NONE;

  if (/^screen|^xterm|^vt100|^vt220|^rxvt|color|ansi|cygwin|linux/i.test(term)) {
    return LEVEL.BASIC;
  }

  const colorterm = process.env.COLORTERM;
  if (colorterm === 'truecolor' || colorterm === '24bit') return LEVEL.TRUECOLOR;
  if (colorterm) return LEVEL.ANSI256;

  if (/-256(color)?$/i.test(term)) return LEVEL.ANSI256;
  if (/-truecolor$/i.test(term)) return LEVEL.TRUECOLOR;

  return LEVEL.BASIC;
}

export function supportsColor(stream = process.stdout) {
  return detectColorLevel(stream) > LEVEL.NONE;
}

import { LEVEL } from './color-support.js';

const CODES = {
  reset: 0,
  bold: 1,
  red: 31,
  green: 32,
  yellow: 33,
  blue: 34,
  magenta: 35,
  cyan: 36,
};

const FG_256 = {
  red: 196,
  green: 46,
  yellow: 226,
  blue: 21,
  magenta: 201,
  cyan: 51,
};

const FG_RGB = {
  red: [255, 85, 85],
  green: [80, 250, 123],
  yellow: [241, 250, 140],
  blue: [98, 114, 164],
  magenta: [255, 121, 198],
  cyan: [139, 233, 253],
};

const noColor = (text) => text;

export function createStyler(level) {
  if (level <= LEVEL.NONE) {
    return { level, color: noColor, bold: noColor, style: noColor };
  }

  const style = (text, ...names) => {
    const codes = names
      .map((name) => {
        if (name === 'bold') return '1';
        if (level >= LEVEL.TRUECOLOR && FG_RGB[name]) {
          const [r, g, b] = FG_RGB[name];
          return `38;2;${r};${g};${b}`;
        }
        if (level >= LEVEL.ANSI256 && FG_256[name]) {
          return `38;5;${FG_256[name]}`;
        }
        if (CODES[name] !== undefined) return String(CODES[name]);
        return null;
      })
      .filter(Boolean);

    if (codes.length === 0) return text;
    return `\u001b[${codes.join(';')}m${text}\u001b[${CODES.reset}m`;
  };

  return {
    level,
    style,
    color: (text, name) => style(text, name),
    bold: (text) => style(text, 'bold'),
  };
}

#!/usr/bin/env node
import { detectColorLevel, LEVEL } from '../src/color-support.js';
import { createStyler } from '../src/ansi.js';

const LEVEL_NAMES = {
  [LEVEL.NONE]: 'none',
  [LEVEL.BASIC]: 'basic (16 colors)',
  [LEVEL.ANSI256]: 'ansi256 (256 colors)',
  [LEVEL.TRUECOLOR]: 'truecolor (16m colors)',
};

function main() {
  const args = process.argv.slice(2);
  const level = detectColorLevel(process.stdout);
  const { style, bold } = createStyler(level);

  if (args.includes('--json')) {
    process.stdout.write(
      JSON.stringify({ supportsColor: level > LEVEL.NONE, level }) + '\n',
    );
    return;
  }

  const text = args.length > 0 ? args.join(' ') : 'Hello, colored world!';

  console.log(`${bold('Terminal color support:')} ${style(LEVEL_NAMES[level], 'cyan')}`);
  console.log(style(text, 'green'));
}

main();

